head.b:skin:
/* ----------------------------------------------- Theme Name: Nova Blogger Pro Author: Generated for vigarepo2/Blogger Version: 1.0.0 Description: Responsive Blogger XML theme with premium magazine UI, dark mode, sticky header, widget-ready layout and clean typography. -----------------------------------------------
<Variable name="keycolor" description="Accent color" type="color" default="#635bff" value="#635bff"/> <Variable name="body.background" description="Page background" type="color" default="#f6f7fb" value="#f6f7fb"/> <Variable name="body.text.color" description="Text color" type="color" default="#111827" value="#111827"/> <Variable name="link.color" description="Link color" type="color" default="#4f46e5" value="#4f46e5"/> */
:root{--bg:#f6f7fb;--surface:#fff;--surface-2:#f1f4f9;--text:#111827;--muted:#667085;--line:#e5e7eb;--accent:#635bff;--accent-2:#08a88a;--danger:#ef4444;--shadow:0 24px 80px rgba(15,23,42,.12);--soft-shadow:0 12px 40px rgba(15,23,42,.08);--radius:24px;--radius-sm:16px;--max:1180px;--font:Inter,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;--display:Sora,Inter,system-ui,sans-serif}html{scroll-behavior:smooth}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at top left,rgba(99,91,255,.12),transparent 34rem),radial-gradient(circle at top right,rgba(8,168,138,.12),transparent 28rem),var(--bg);color:var(--text);font-family:var(--font);font-size:16px;line-height:1.7;text-rendering:optimizeLegibility;-webkit-font-smoothing:antialiased}body.dark{--bg:#090b10;--surface:#111827;--surface-2:#182030;--text:#f8fafc;--muted:#a6adbb;--line:#263244;--shadow:0 24px 80px rgba(0,0,0,.36);--soft-shadow:0 12px 36px rgba(0,0,0,.3)}a{color:inherit;text-decoration:none}a:hover{color:var(--accent)}img{max-width:100%;height:auto;border-radius:18px}button,input,textarea,select{font:inherit}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}.progress{position:fixed;top:0;left:0;height:3px;width:0;background:linear-gradient(90deg,var(--accent),var(--accent-2));z-index:9999}.site-wrap{min-height:100vh}.container{width:min(var(--max),calc(100% - 32px));margin-inline:auto}.topbar{position:sticky;top:0;z-index:50;backdrop-filter:blur(18px);background:color-mix(in srgb,var(--bg) 78%,transparent);border-bottom:1px solid color-mix(in srgb,var(--line) 74%,transparent)}.nav{height:76px;display:flex;align-items:center;gap:18px}.brand{display:flex;align-items:center;gap:12px;min-width:0}.brand-mark{width:42px;height:42px;border-radius:15px;background:linear-gradient(135deg,var(--accent),var(--accent-2));display:grid;place-items:center;color:#fff;font-weight:900;box-shadow:0 14px 30px rgba(99,91,255,.28)}.brand-text{display:flex;flex-direction:column;line-height:1.1;min-width:0}.brand-name{font-family:var(--display);font-size:1.05rem;font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.brand-sub{font-size:.75rem;color:var(--muted);font-weight:600}.nav-spacer{flex:1}.nav-actions{display:flex;align-items:center;gap:10px}.icon-btn,.search-submit{border:1px solid var(--line);background:var(--surface);color:var(--text);height:42px;min-width:42px;border-radius:14px;display:grid;place-items:center;cursor:pointer;box-shadow:0 4px 16px rgba(15,23,42,.04)}.icon-btn:hover,.search-submit:hover{transform:translateY(-1px);box-shadow:var(--soft-shadow)}.header-search{display:flex;align-items:center;gap:8px;background:var(--surface);border:1px solid var(--line);border-radius:16px;padding:5px 6px 5px 14px;min-width:280px}.header-search input{border:0;outline:0;background:transparent;color:var(--text);width:100%}.header-search input::placeholder{color:var(--muted)}.header-menu{display:flex;align-items:center;gap:8px}.header-menu .widget{margin:0}.PageList ul{display:flex;align-items:center;gap:4px;list-style:none;margin:0;padding:0}.PageList li a{display:block;padding:10px 12px;border-radius:12px;color:var(--muted);font-weight:700;font-size:.92rem}.PageList li.selected a,.PageList li a:hover{background:var(--surface);color:var(--text)}.hero{padding:62px 0 34px}.hero-card{position:relative;overflow:hidden;border:1px solid var(--line);border-radius:calc(var(--radius) + 8px);background:linear-gradient(135deg,color-mix(in srgb,var(--surface) 94%,var(--accent)),var(--surface));box-shadow:var(--shadow);padding:44px}.hero-card::before{content:"";position:absolute;inset:auto -80px -140px auto;width:360px;height:360px;border-radius:999px;background:radial-gradient(circle,rgba(99,91,255,.28),transparent 64%)}.eyebrow{display:inline-flex;align-items:center;gap:8px;border:1px solid var(--line);background:var(--surface);border-radius:999px;padding:8px 12px;color:var(--muted);font-size:.8rem;font-weight:800;text-transform:uppercase;letter-spacing:.08em}.eyebrow::before{content:"";width:8px;height:8px;border-radius:999px;background:var(--accent-2);box-shadow:0 0 0 6px rgba(8,168,138,.12)}.hero h1{position:relative;margin:18px 0 10px;max-width:800px;font-family:var(--display);font-size:clamp(2.2rem,6vw,5rem);line-height:.98;letter-spacing:-.06em}.hero p{position:relative;max-width:720px;margin:0;color:var(--muted);font-size:1.08rem}.hero-actions{position:relative;display:flex;flex-wrap:wrap;gap:12px;margin-top:26px}.btn{display:inline-flex;align-items:center;gap:10px;padding:12px 16px;border-radius:15px;border:1px solid var(--line);background:var(--surface);font-weight:800}.btn.primary{background:linear-gradient(135deg,var(--accent),#7c3aed);color:#fff;border-color:transparent;box-shadow:0 18px 36px rgba(99,91,255,.24)}.ticker{margin:20px 0 0;display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.metric{border:1px solid var(--line);border-radius:18px;background:color-mix(in srgb,var(--surface) 74%,transparent);padding:14px}.metric strong{display:block;font-family:var(--display);font-size:1.1rem}.metric span{color:var(--muted);font-size:.82rem;font-weight:700}.layout{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:28px;align-items:start;padding:28px 0 72px}.content,.sidebar{min-width:0}.widget{margin:0 0 22px}.main-section .widget{margin:0}.Blog .blog-posts,.main-section .blog-posts{display:grid;gap:24px}.post-outer,.Blog .post,.blog-posts .post,.date-outer{background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--soft-shadow);padding:26px;overflow:hidden}.post-title,.entry-title{margin:0 0 12px;font-family:var(--display);font-weight:800;letter-spacing:-.04em;line-height:1.12;font-size:clamp(1.45rem,3vw,2.55rem)}.post-title a,.entry-title a{color:var(--text)}.post-header,.post-footer,.post-meta,.date-header{color:var(--muted);font-size:.88rem;font-weight:700}.post-body{font-size:1.02rem;color:color-mix(in srgb,var(--text) 92%,var(--muted));overflow-wrap:anywhere}.post-body h2,.post-body h3{font-family:var(--display);letter-spacing:-.04em;line-height:1.16}.post-body h2{font-size:1.9rem;margin-top:1.4em}.post-body h3{font-size:1.45rem;margin-top:1.2em}.post-body p{margin:0 0 1.05em}.post-body blockquote{margin:24px 0;padding:18px 20px;border-left:4px solid var(--accent);background:var(--surface-2);border-radius:0 16px 16px 0;color:var(--text)}.post-body pre{position:relative;overflow:auto;padding:18px;border-radius:18px;background:#0b1020;color:#e5e7eb;line-height:1.6}.post-body code{font-family:"SFMono-Regular",Consolas,"Liberation Mono",monospace;font-size:.92em}.jump-link a,.more-link{display:inline-flex;align-items:center;gap:8px;margin-top:8px;padding:10px 14px;border-radius:14px;background:var(--text);color:var(--bg);font-weight:800}.breadcrumbs,.status-msg-wrap{background:var(--surface);border:1px solid var(--line);border-radius:18px;padding:14px 16px;margin:0 0 18px;color:var(--muted);box-shadow:var(--soft-shadow)}.comments,.comment-thread,.comment-form{background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);padding:22px;margin-top:24px}.sidebar .widget,.footer-grid .widget,.hero-ad .widget,.below-header .widget{border:1px solid var(--line);background:color-mix(in srgb,var(--surface) 94%,transparent);border-radius:var(--radius);box-shadow:var(--soft-shadow);padding:22px}.sidebar .widget h2,.footer-grid .widget h2,.widget-title{margin:0 0 14px;font-family:var(--display);font-size:1.05rem;letter-spacing:-.03em}.sidebar ul,.footer-grid ul{list-style:none;padding:0;margin:0}.sidebar li,.footer-grid li{padding:10px 0;border-bottom:1px solid var(--line)}.sidebar li:last-child,.footer-grid li:last-child{border-bottom:0}.Label a,.label-size a{display:inline-flex;margin:5px 5px 0 0;padding:7px 10px;border-radius:999px;border:1px solid var(--line);background:var(--surface-2);color:var(--muted);font-size:.82rem;font-weight:800}.PopularPosts .item-title{font-weight:800}.PopularPosts .item-snippet{color:var(--muted)}.blog-pager{display:flex;justify-content:space-between;gap:12px;margin:24px 0}.blog-pager a{padding:12px 14px;border-radius:14px;background:var(--surface);border:1px solid var(--line);font-weight:800}.below-header{margin-top:18px}.footer{border-top:1px solid var(--line);background:color-mix(in srgb,var(--surface) 50%,transparent);padding:46px 0 26px}.footer-grid{display:grid;grid-template-columns:2fr 1fr 1fr;gap:22px}.footer-bottom{display:flex;justify-content:space-between;gap:18px;align-items:center;color:var(--muted);font-size:.9rem;font-weight:600;padding-top:24px;margin-top:24px;border-top:1px solid var(--line)}.floating-tools{position:fixed;right:18px;bottom:18px;display:flex;flex-direction:column;gap:10px;z-index:40}.to-top{opacity:0;pointer-events:none}.to-top.show{opacity:1;pointer-events:auto}.ad-slot{min-height:90px;display:grid;place-items:center;border:1px dashed var(--line);border-radius:18px;color:var(--muted);font-weight:800;background:var(--surface-2)}.error_page .layout,.error_page .content{display:block}.mobile-menu-toggle{display:none}.copy-code{position:absolute;right:10px;top:10px;border:0;border-radius:10px;padding:6px 9px;background:rgba(255,255,255,.12);color:#fff;font-size:.75rem;cursor:pointer}@media (max-width:980px){.layout{grid-template-columns:1fr}.sidebar{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.sidebar .widget{margin:0}.header-search{min-width:220px}.ticker{grid-template-columns:1fr 1fr 1fr}.footer-grid{grid-template-columns:1fr 1fr}}@media (max-width:760px){.container{width:min(100% - 22px,var(--max))}.nav{height:68px}.brand-sub{display:none}.header-search{display:none}.mobile-menu-toggle{display:grid}.header-menu{position:absolute;left:11px;right:11px;top:74px;display:none;background:var(--surface);border:1px solid var(--line);border-radius:20px;box-shadow:var(--shadow);padding:12px}.header-menu.open{display:block}.PageList ul{display:block}.PageList li a{padding:12px 14px}.hero{padding:34px 0 18px}.hero-card{padding:28px 20px;border-radius:26px}.ticker,.sidebar,.footer-grid{grid-template-columns:1fr}.layout{padding-top:18px;gap:20px}.post-outer,.Blog .post,.blog-posts .post,.date-outer{padding:20px;border-radius:22px}.footer-bottom{display:block}.floating-tools{right:12px;bottom:12px}.icon-btn{height:40px;min-width:40px}}@media print{.topbar,.floating-tools,.sidebar,.footer,.hero-actions,.blog-pager{display:none!important}body{background:#fff;color:#000}.layout{display:block}.post-outer,.Blog .post,.blog-posts .post,.date-outer{box-shadow:none;border:0;padding:0}}

body.script:
(function(){
  var body=document.body,root=document.documentElement,themeBtn=document.getElementById('themeToggle'),menuBtn=document.getElementById('menuToggle'),menu=document.getElementById('mainMenu'),toTop=document.getElementById('toTop'),progress=document.getElementById('readProgress'),year=document.getElementById('year');
  if(year){year.textContent=new Date().getFullYear();}
  try{if(localStorage.getItem('novaTheme')==='dark'){body.classList.add('dark');}}catch(e){}
  if(themeBtn){themeBtn.addEventListener('click',function(){body.classList.toggle('dark');try{localStorage.setItem('novaTheme',body.classList.contains('dark')?'dark':'light');}catch(e){}});}
  if(menuBtn&&menu){menuBtn.addEventListener('click',function(){menu.classList.toggle('open');});}
  function onScroll(){var st=window.scrollY||root.scrollTop,dh=root.scrollHeight-root.clientHeight,p=dh>0?st/dh*100:0;if(progress){progress.style.width=p+'%';}if(toTop){toTop.classList.toggle('show',st>500);}}
  window.addEventListener('scroll',onScroll,{passive:true});onScroll();
  if(toTop){toTop.addEventListener('click',function(){window.scrollTo({top:0,behavior:'smooth'});});}
  document.querySelectorAll('.post-body pre').forEach(function(pre){var b=document.createElement('button');b.type='button';b.className='copy-code';b.textContent='Copy';b.addEventListener('click',function(){var t=pre.innerText||pre.textContent;navigator.clipboard&&navigator.clipboard.writeText(t).then(function(){b.textContent='Copied';setTimeout(function(){b.textContent='Copy';},1200);});});pre.appendChild(b);});
})();
